import { useAuth } from '../context/AuthContext';

const InnovationCard = ({ innovation, onVote, isUserOwn = false }) => {
  const { user } = useAuth();

  const handleVoteClick = () => {
    if (!user) {
      alert("Please log in to vote on innovations.");
      return;
    }
    onVote(innovation._id);
  };

  return (
    <div className="bg-[#fffaf1] border border-[#e2d4b5] rounded-2xl shadow-md 
                    hover:shadow-xl hover:-translate-y-1 transition-all duration-300 p-6">

      {/* ---------- HEADER ---------- */}
      <div className="flex justify-between items-start mb-5">

        {/* Title + State Badge */}
        <div className="flex-1">
          <h3 className="text-2xl font-semibold text-[#7a3b1e] mb-2">
            {innovation.title}
          </h3>

          <span className="inline-block bg-[#e5f0ff] text-blue-800 text-sm 
                           px-3 py-1 rounded-full border border-blue-200">
            {innovation.state}
          </span>
        </div>

        {/* ---------- VOTE SECTION ---------- */}
        <div className="flex flex-col items-center ml-4">

          {isUserOwn ? (
            <div className="text-center">
              <div className="text-sm text-green-600 font-medium mb-1">Your Innovation</div>
              <div className="text-3xl font-bold text-green-600">{innovation.votes}</div>
              <div className="text-xs text-gray-500">votes received</div>
            </div>
          ) : user ? (
            <>
              <button
                onClick={handleVoteClick}
                disabled={innovation.voters?.includes(user.id)}
                className={`px-4 py-2 rounded-lg shadow font-medium mb-2 transition 
                  ${
                    innovation.voters?.includes(user.id)
                      ? "bg-green-100 text-green-700 cursor-not-allowed"
                      : "bg-[#b2541a] text-white hover:bg-[#8d3c11]"
                  }
                `}
              >
                {innovation.voters?.includes(user.id) ? "✅ Voted" : "👍 Vote"}
              </button>

              <div className="text-center">
                <div className="text-3xl font-bold text-green-600">{innovation.votes}</div>
                <div className="text-xs text-gray-500">votes</div>
              </div>
            </>
          ) : (
            <div className="text-center">
              <div className="text-xs text-gray-500 mb-1">Login to vote</div>
              <div className="text-3xl font-bold text-green-600">{innovation.votes}</div>
              <div className="text-xs text-gray-500">votes</div>
            </div>
          )}

        </div>
      </div>

      {/* ---------- DESCRIPTION ---------- */}
      <p className="text-gray-700 mb-5 leading-relaxed">
        {innovation.description}
      </p>

      {/* ---------- FOOTER ---------- */}
      <div className="flex justify-between items-center text-sm text-gray-600 
                      border-t border-[#e2d4b5] pt-4">

        <div>
          {innovation.submittedBy ? (
            <span>Submitted by: {innovation.submittedBy.name || "Anonymous"}</span>
          ) : (
            <span>Anonymous submission</span>
          )}
        </div>

        <div>{new Date(innovation.createdAt).toLocaleDateString()}</div>
      </div>
    </div>
  );
};

export default InnovationCard;
